-- library-source: byrne_2018_matador sha256:3a1a9b40656ca0126a155a30ed752800cb8c2de4c1eb14e4a0c95489ac6245af
select private.library_replace_source(
$lib${"slug":"byrne_2018_matador","title":"Intermittent energy restriction improves weight loss efficiency in obese men: the MATADOR study","authors":["Byrne NM","Sainsbury A","King NA","Hills AP","Wood RE"],"year":2018,"doi":"10.1038/ijo.2017.206","url":"https://doi.org/10.1038/ijo.2017.206","licence":"CC BY-NC-ND (open access); own-words summary, no text copied","region":["global"],"topics":["nutrition","energy-balance","fat-loss","diet-break","metabolic-adaptation"],"evidence_level":"randomised controlled trial (51 men with obesity)","kind":"paper"}$lib$::jsonb,
$lib$[{"ordinal":0,"section":"What the trial did","header":"Source: Byrne et al. 2018 (MATADOR), Intermittent energy restriction improves weight loss efficiency in obese men: the MATADOR study. Section: What the trial did.","body":"Fifty-one men with obesity were randomly placed on one of two diets. Both groups ate 67 percent of what they needed to hold their weight for 16 weeks in total. One group did this continuously. The other did it as eight blocks of two weeks, with a two-week block of eating at maintenance between them, so their diet lasted 30 weeks from start to finish. Forty-seven men began the diet phase, and the main results below are for the 19 continuous and 17 intermittent dieters who finished as planned.","token_count":165},{"ordinal":1,"section":"Results","header":"Source: Byrne et al. 2018 (MATADOR), Intermittent energy restriction improves weight loss efficiency in obese men: the MATADOR study. Section: Results.","body":"The intermittent group lost more weight (14.1 against 9.1 kg) and more fat (12.3 against 8.0 kg). Loss of fat-free mass was similar in the two groups (1.8 against 1.2 kg). Body weight barely moved during the seven maintenance blocks. The fall in resting energy expenditure was not different between groups, but once it was adjusted for changes in body composition the fall was smaller in the intermittent group. The authors read this as the maintenance blocks reducing the body's compensatory slowdown, which made the diet more efficient.","token_count":173},{"ordinal":2,"section":"Practical reading and limits","header":"Source: Byrne et al. 2018 (MATADOR), Intermittent energy restriction improves weight loss efficiency in obese men: the MATADOR study. Section: Practical reading and limits.","body":"The participants were men with obesity (average weight about 110 kg), so the result is not proof for a lean, trained person. The intermittent group took 30 weeks to complete the same amount of dieting, so extra time passed, and the main analysis covered only the people who completed the protocol. A later trial in trained adults (the ICECAP trial) did not find extra fat loss from breaks. Coach should present a planned break as a reasonable option that helps some people stay on track and may help a little with efficiency, not as a requirement.","token_count":180}]$lib$::jsonb
);

-- library-source: peos_2021_icecap sha256:d02a83434414e2031150bc89aa476dc1b0dd1b4050d678de9bac295740b4f7c7
select private.library_replace_source(
$lib${"slug":"peos_2021_icecap","title":"Continuous versus intermittent dieting for fat loss and fat-free mass retention in resistance-trained adults: the ICECAP trial","authors":["Peos JJ","Helms ER","Fournier PA","Ong J","Hall C","Krieger J"],"year":2021,"doi":"10.1249/mss.0000000000002636","url":"https://doi.org/10.1249/mss.0000000000002636","licence":"Publisher copyright (no open licence found); stored as an own-words summary with citation","region":["global"],"topics":["nutrition","energy-balance","fat-loss","diet-break","training","hunger"],"evidence_level":"randomised controlled trial (61 resistance-trained adults)","kind":"paper"}$lib$::jsonb,
$lib$[{"ordinal":0,"section":"What the trial did","header":"Source: Peos et al. 2021 (ICECAP), Continuous versus intermittent dieting for fat loss and fat-free mass retention in resistance-trained adults: the ICECAP trial. Section: What the trial did.","body":"Sixty-one resistance-trained adults (32 of them women, average age about 29, about 25 percent body fat) were randomly assigned to a moderate calorie deficit in one of two patterns. One group dieted for 12 weeks without a break. The other dieted in four blocks of three weeks, each followed by a week of eating at maintenance, which made 15 weeks in total. All results were analysed according to the group each person was assigned to.","token_count":157},{"ordinal":1,"section":"Results","header":"Source: Peos et al. 2021 (ICECAP), Continuous versus intermittent dieting for fat loss and fat-free mass retention in resistance-trained adults: the ICECAP trial. Section: Results.","body":"After the deficit, the groups did not differ in fat mass, fat-free mass or body weight, and there was no difference in muscle strength or endurance, resting energy expenditure, the hormones measured (leptin, testosterone, thyroid hormone, IGF-1, ghrelin), sleep, or eating-disorder-related behaviours. The group that took breaks reported lower hunger and less desire to eat, and greater satisfaction with the diet.","token_count":149},{"ordinal":2,"section":"Practical reading and limits","header":"Source: Peos et al. 2021 (ICECAP), Continuous versus intermittent dieting for fat loss and fat-free mass retention in resistance-trained adults: the ICECAP trial. Section: Practical reading and limits.","body":"For a trained person, breaks did not speed up fat loss or protect muscle better in this trial, but they made dieting feel easier. That is a good reason to offer a break to someone who is tired of dieting, and a poor reason to promise faster results. The trial lasted 12 weeks of deficit, so it does not say what happens over a very long diet.","token_count":136}]$lib$::jsonb
);

-- library-source: trexler_2014_metabolic_adaptation sha256:3ae6c80f10a8e1a8eb11ae1e3152cd18aeb374b9a7229b4ef83051b41ecd1037
select private.library_replace_source(
$lib${"slug":"trexler_2014_metabolic_adaptation","title":"Metabolic adaptation to weight loss: implications for the athlete","authors":["Trexler ET","Smith-Ryan AE","Norton LE"],"year":2014,"doi":"10.1186/1550-2783-11-7","url":"https://doi.org/10.1186/1550-2783-11-7","licence":"CC BY 2.0 (open access); own-words summary","region":["global"],"topics":["nutrition","energy-balance","fat-loss","metabolic-adaptation","diet-break","weight-maintenance"],"evidence_level":"narrative review","kind":"paper"}$lib$::jsonb,
$lib$[{"ordinal":0,"section":"What happens in a long deficit","header":"Source: Trexler et al. 2014, Metabolic adaptation to weight loss: implications for the athlete. Section: What happens in a long deficit.","body":"Eating less is followed by changes in several hormones: leptin, insulin, testosterone and thyroid hormones tend to fall, while ghrelin (which raises hunger) and cortisol tend to rise. Total daily energy expenditure falls, and the fall is often bigger than the lost body mass alone would predict. This extra drop is called adaptive thermogenesis. The energy spent on exercise and on everyday movement outside exercise (fidgeting, walking about) also falls. Some of these changes persist after the diet, even in people who have kept the lower weight for more than a year.","token_count":177},{"ordinal":1,"section":"What the authors recommend","header":"Source: Trexler et al. 2014, Metabolic adaptation to weight loss: implications for the athlete. Section: What the authors recommend.","body":"The size of the adaptation is probably in proportion to the size of the deficit, so the review advises using the smallest deficit that still gives appreciable weight loss, treating weight loss as a series of steps, and adjusting food or activity when progress flattens to open the deficit again. Large deficits cost more lean mass and hurt performance and recovery. A structured resistance training programme and enough protein help protect lean mass, and diets high in protein are linked with more fullness and more heat production from food.","token_count":169},{"ordinal":2,"section":"Refeeds, reverse dieting and regaining","header":"Source: Trexler et al. 2014, Metabolic adaptation to weight loss: implications for the athlete. Section: Refeeds, reverse dieting and regaining.","body":"Refeeds are short spells of eating slightly above maintenance, mostly extra carbohydrate, used in physique sports to lift leptin. Leptin does respond in the short term, but the measured rise in energy expenditure was modest, and the authors say there is not enough evidence that refeeds help a long diet. Reverse dieting (raising calories in small steps after a diet) is also unproven. After a diet, regained weight comes back mostly as fat, and leaner people can overshoot their old body fat. Repeated cycles of loss and regain are linked with long-term weight gain in weight-class athletes.","token_count":185},{"ordinal":3,"section":"Practical reading and limits","header":"Source: Trexler et al. 2014, Metabolic adaptation to weight loss: implications for the athlete. Section: Practical reading and limits.","body":"This is the explanation for a plateau or a rising appetite after a big loss: it is expected biology, not weak willpower, and the answer is patience, smaller deficits and keeping training and protein up. Most of the underlying research is on animals or on people with overweight who do not train, so how strongly it applies to a lean, trained person is uncertain. Refeeds and reverse dieting should be described as popular but unproven.","token_count":143}]$lib$::jsonb
);

-- library-source: mountjoy_2023_reds sha256:432bd201506460044c218d9661ef4bc45e8e6d6af644239f33f0f066e46e706d
select private.library_replace_source(
$lib${"slug":"mountjoy_2023_reds","title":"2023 International Olympic Committee's (IOC) consensus statement on Relative Energy Deficiency in Sport (REDs)","authors":["Mountjoy M","Ackerman KE","Bailey DM","Burke LM","Constantini N","Hackney AC"],"year":2023,"doi":"10.1136/bjsports-2023-106994","url":"https://doi.org/10.1136/bjsports-2023-106994","licence":"Publisher copyright (no open licence found); stored as an own-words summary with citation","region":["global"],"topics":["nutrition","energy-balance","low-energy-availability","recovery","safety","fat-loss"],"evidence_level":"expert consensus statement","kind":"guideline"}$lib$::jsonb,
$lib$[{"ordinal":0,"section":"What REDs is","header":"Source: Mountjoy et al. 2023 (IOC), 2023 International Olympic Committee's (IOC) consensus statement on Relative Energy Deficiency in Sport (REDs). Section: What REDs is.","body":"Relative Energy Deficiency in Sport (REDs) is a syndrome of harmful health and performance effects seen in female and male athletes who are exposed to low energy availability, meaning they take in too little energy for the energy their exercise uses. The panel first described it in 2014 and updated it in 2023, after more than 170 new original studies since the 2018 statement.","token_count":138},{"ordinal":1,"section":"What has changed","header":"Source: Mountjoy et al. 2023 (IOC), 2023 International Olympic Committee's (IOC) consensus statement on Relative Energy Deficiency in Sport (REDs). Section: What has changed.","body":"The 2023 statement adds evidence on the part played by low carbohydrate availability and by mental health, and more data on low energy availability in males. It updates the health and performance models and introduces a physiological model that shows how a problematic or an adaptable period of low energy availability, together with personal factors, leads to different outcomes.","token_count":139},{"ordinal":2,"section":"Assessment, prevention and treatment","header":"Source: Mountjoy et al. 2023 (IOC), 2023 International Olympic Committee's (IOC) consensus statement on Relative Energy Deficiency in Sport (REDs). Section: Assessment, prevention and treatment.","body":"The statement sets out safe and effective ways to assess body composition to help prevent REDs, and introduces the REDs Clinical Assessment Tool version 2, which clinicians use to detect and diagnose REDs from the accumulated severity and risk level, with matching advice on training and competition. It also covers principles of prevention and treatment for sports organisations and clinicians.","token_count":148},{"ordinal":3,"section":"Practical reading and limits","header":"Source: Mountjoy et al. 2023 (IOC), 2023 International Olympic Committee's (IOC) consensus statement on Relative Energy Deficiency in Sport (REDs). Section: Practical reading and limits.","body":"This summary is written from the abstract, because the full text could not be fetched, so it does not list individual signs or thresholds. Detection and diagnosis belong to clinicians using the assessment tool, and Coach must never diagnose. The sensible use is to treat steady, large deficits combined with a lot of training as a reason to ask how the person feels, favour smaller deficits and enough food, and suggest a clinician when the picture looks worrying. The statement is aimed at athletes, so applying it to a recreational lifter is an extrapolation.","token_count":187}]$lib$::jsonb
);

-- library-source: varkevisser_2019_weight_loss_maintenance sha256:d0066bcfc2fb4c2944b57c435ae5070d85b6a3eaba2794fad92549ed1e91e040
select private.library_replace_source(
$lib${"slug":"varkevisser_2019_weight_loss_maintenance","title":"Determinants of weight loss maintenance: a systematic review","authors":["Varkevisser RDM","van Stralen MM","Kroeze W","Ket JCF","Steenhuis IHM"],"year":2019,"doi":"10.1111/obr.12772","url":"https://doi.org/10.1111/obr.12772","licence":"CC BY-NC-ND (open access); own-words summary, no text copied","region":["global"],"topics":["nutrition","weight-maintenance","fat-loss","behaviour-change","adherence"],"evidence_level":"systematic review (67 studies)","kind":"paper"}$lib$::jsonb,
$lib$[{"ordinal":0,"section":"What the review did","header":"Source: Varkevisser et al. 2019, Determinants of weight loss maintenance: a systematic review. Section: What the review did.","body":"The reviewers searched for prospective studies of adults with overweight or obesity who lost weight without surgery or medication. From 8,222 articles they selected 67, which together tested 124 possible determinants of keeping weight off: 5 demographic, 59 behavioural, 51 psychological or cognitive and 9 social or environmental. They scored study quality and summarised each determinant by the strength of evidence.","token_count":136},{"ordinal":1,"section":"What predicted success","header":"Source: Varkevisser et al. 2019, Determinants of weight loss maintenance: a systematic review. Section: What predicted success.","body":"Age, gender and socioeconomic status did not predict who kept weight off. Strong evidence supported these as helpful: weighing oneself regularly, monitoring what one eats, increasing physical activity, controlling portions, cutting unhealthy foods, eating less overall, eating more fruit and vegetables and drinking fewer sugary drinks. Self-monitoring of exercise and confidence in one's ability to manage weight and to exercise (self-efficacy) were also positive. Problematic eating predicted regaining, and stress on its own was not a clear predictor.","token_count":171},{"ordinal":2,"section":"Practical reading and limits","header":"Source: Varkevisser et al. 2019, Determinants of weight loss maintenance: a systematic review. Section: Practical reading and limits.","body":"Maintenance is a skill built from ordinary habits: keep tracking weight and food, stay active and stay confident, and it works in both sexes and at all ages. The review is of people with overweight or obesity, so it is only a rough guide for someone who is now at a healthy weight. The social and environmental evidence was thin, and the findings are associations, not proof of cause.","token_count":130}]$lib$::jsonb
);

-- library-source: icmr_nin_2024_dietary_guidelines sha256:7abcb21a5f7016a541bd09aa60e898e3229a4a83f19f9c2db0c69980d9290a0d
select private.library_replace_source(
$lib${"slug":"icmr_nin_2024_dietary_guidelines","title":"Dietary Guidelines for Indians 2024","authors":["ICMR-NIN Expert Committee"],"year":2024,"doi":null,"url":"https://www.nin.res.in/dietaryguidelines/pdfjs/locale/DGI_2024.pdf","licence":"Publisher copyright (ICMR-NIN; free to read online, reproducing it in a product needs written permission); own-words summary with citation","region":["IN"],"topics":["nutrition","protein","fat-loss","energy-balance","activity","guidelines","india"],"evidence_level":"national dietary guidelines","kind":"guideline"}$lib$::jsonb,
$lib$[{"ordinal":0,"section":"Body weight and weight loss","header":"Source: ICMR-NIN 2024, Dietary Guidelines for Indians 2024. Section: Body weight and weight loss.","body":"The guidelines apply Asian BMI cut-offs because Asians tend to carry more body fat at a given BMI: a healthy range is 18.5 to 23, overweight is above 23 up to 27.5 and obesity is above 27.5. They also use waist circumference, which is linked to higher risk above 90 cm in men and above 80 cm in women. Weight loss should be gradual, with half a kilogram a week called safe. A weight-loss diet should not go below 1,000 kcal a day and should be nutritionally complete, and the guidelines advise against deficits above 40 percent of daily energy needs. Rapid loss and anti-obesity drugs should be avoided.","token_count":176},{"ordinal":1,"section":"Protein","header":"Source: ICMR-NIN 2024, Dietary Guidelines for Indians 2024. Section: Protein.","body":"The guidelines give 0.83 g of protein per kg a day as the recommended allowance for healthy men and women, with protein supplying 10 to 15 percent of energy, and say a varied diet meets this, including a vegetarian one. They advise getting protein from food rather than protein powders, and warn that very high intakes from powders over long periods are not advisable. They accept that a higher share, 15 percent of energy, may help keep muscle during a calorie deficit. They note that protein only builds muscle with enough energy from carbohydrate and fat and with resistance exercise, and that intakes above about 1.6 g per kg a day add no further muscle in resistance training.","token_count":190},{"ordinal":2,"section":"Food pattern and activity","header":"Source: ICMR-NIN 2024, Dietary Guidelines for Indians 2024. Section: Food pattern and activity.","body":"The guidelines are food-based: a variety of whole grains and millets, pulses, vegetables, fruit, milk or curd, and nuts, with cereals and pulses combined (about 3 to 1 by raw weight) for better protein quality. They advise limiting sugar, salt, refined oil and ultra-processed foods, and avoiding soft drinks and alcohol. For activity, they recommend a combination of aerobic, strength, balance and flexibility work, including yoga, with muscle-strengthening at least two days a week for adults, and sleep of 6 to 8 hours a day.","token_count":156},{"ordinal":3,"section":"Practical reading and limits","header":"Source: ICMR-NIN 2024, Dietary Guidelines for Indians 2024. Section: Practical reading and limits.","body":"For Indian users, use these foods and cut-offs alongside the sports papers: a person at a BMI of 23 is at the top of the Asian healthy range, not comfortably inside the usual 18.5 to 25. Where the guidelines and the sports-nutrition papers disagree, such as protein powders and the daily protein target for lifters, Coach should say the two sources differ and let the athlete's own needs and goals decide, with Tracend's rules setting the numbers. The guidelines are for the general population, not for athletes, and are not a basis for medical diets.","token_count":163}]$lib$::jsonb
);

-- library-source: vella_2010_alcohol_recovery sha256:a61ed21c17abda804aa05a46a0b4c333a9c225b593435c11abc73990f7e53fe0
select private.library_replace_source(
$lib${"slug":"vella_2010_alcohol_recovery","title":"Alcohol, athletic performance and recovery","authors":["Vella LD","Cameron-Smith D"],"year":2010,"doi":"10.3390/nu2080781","url":"https://doi.org/10.3390/nu2080781","licence":"CC BY 3.0 (open access); own-words summary","region":["global"],"topics":["alcohol","recovery","nutrition","sleep","hydration","performance"],"evidence_level":"narrative review","kind":"paper"}$lib$::jsonb,
$lib$[{"ordinal":0,"section":"Effects on the body","header":"Source: Vella and Cameron-Smith 2010, Alcohol, athletic performance and recovery. Section: Effects on the body.","body":"Alcohol acts as a diuretic, widens blood vessels, interferes with the body's temperature control and lowers work tolerance in both hot and cold conditions. It impairs the liver's glucose output and can reduce how much glucose muscle takes up and stores. It slows reaction time, balance and fine motor control in proportion to the dose, and it lowers sleep depth and shortens REM sleep.","token_count":125},{"ordinal":1,"section":"Performance","header":"Source: Vella and Cameron-Smith 2010, Alcohol, athletic performance and recovery. Section: Performance.","body":"Evidence on endurance is mixed, with harm once blood alcohol is high enough. For strength and power the review found most studies did not show a clear effect of alcohol taken just before testing, though one sprint study did. The review stresses that few clinical trials exist.","token_count":95},{"ordinal":2,"section":"Recovery","header":"Source: Vella and Cameron-Smith 2010, Alcohol, athletic performance and recovery. Section: Recovery.","body":"Results on muscle-damage markers and on rebuilding energy stores after exercise were inconclusive, and glycogen replenished within 24 hours in one study even after alcohol. Alcohol lowers muscle protein synthesis in a dose-dependent way when no exercise is done, but how that applies after a hard lifting session has not been tested properly in humans. The clearest functional finding came from one research group: after hard eccentric exercise, drinking about 1 g of alcohol per kg of body weight made the loss of muscle force at 36 hours worse.","token_count":162},{"ordinal":3,"section":"Practical reading and limits","header":"Source: Vella and Cameron-Smith 2010, Alcohol, athletic performance and recovery. Section: Practical reading and limits.","body":"Drinking is unlikely to cancel out a training programme in one night, but it can make the next sessions worse through poorer sleep, dehydration and slower recovery from damaging exercise, and replacing food with alcohol cuts the carbohydrate and protein the muscles need. The review is from 2010 and includes few human trials, so Coach should speak in terms of \"may\" and not give precise limits. Coach should not encourage drinking, nor lecture an adult about it.","token_count":146}]$lib$::jsonb
);

-- library-source: zhu_2024_motivational_interviewing sha256:9f4f809b2d8d16ce4adfd7c63678496ce5ab2b9ae93fa68fb8110ad8db7153ea
select private.library_replace_source(
$lib${"slug":"zhu_2024_motivational_interviewing","title":"Effectiveness of behavioural interventions with motivational interviewing on physical activity outcomes in adults: systematic review and meta-analysis","authors":["Zhu S","Sinha D","Kirk M","Michalopoulou M","Hajizadeh A","Wren G"],"year":2024,"doi":"10.1136/bmj-2023-078713","url":"https://doi.org/10.1136/bmj-2023-078713","licence":"CC BY 4.0 (open access); own-words summary","region":["global"],"topics":["behaviour-change","coaching-communication","activity","adherence","motivation"],"evidence_level":"systematic review and meta-analysis (97 randomised trials)","kind":"paper"}$lib$::jsonb,
$lib$[{"ordinal":0,"section":"What the review did","header":"Source: Zhu et al. 2024, Effectiveness of behavioural interventions with motivational interviewing on physical activity outcomes in adults: systematic review and meta-analysis. Section: What the review did.","body":"Motivational interviewing is a counselling style in which the helper asks open questions, reflects back what the person says and draws out their own reasons for change. The reviewers searched seven databases up to March 2023 for randomised trials comparing a behavioural programme that included motivational interviewing with a similar programme without it, in adults, measuring physical activity or sedentary time. They found 129 papers on 97 trials with 27,811 people.","token_count":170},{"ordinal":1,"section":"Results","header":"Source: Zhu et al. 2024, Effectiveness of behavioural interventions with motivational interviewing on physical activity outcomes in adults: systematic review and meta-analysis. Section: Results.","body":"Programmes that included motivational interviewing did better than their comparators on total physical activity (about 1,323 extra steps a day, low-certainty evidence), on moderate to vigorous activity (about 95 extra minutes a week, very low certainty) and on sedentary time (about 51 minutes a day less, very low certainty). But when the comparator was a programme of similar intensity, there was no evidence of a difference. The effect faded over time, and there was no evidence of a benefit beyond one year. Most trials enrolled people with a health condition, and for the general population there was no evidence of an effect on moderate to vigorous activity or sedentary time.","token_count":220},{"ordinal":2,"section":"Practical reading and limits","header":"Source: Zhu et al. 2024, Effectiveness of behavioural interventions with motivational interviewing on physical activity outcomes in adults: systematic review and meta-analysis. Section: Practical reading and limits.","body":"A conversational, question-led style is a sensible way to coach, but it should not be sold as a proven way to raise activity: the benefit could not be isolated to the interviewing style itself, it fades, and the certainty is low. Coach can ask what the person wants and what gets in the way before suggesting changes, and should keep supporting them over months and not expect one chat to last. Most of the evidence is from people with health conditions, so for healthy lifters it is an extrapolation.","token_count":180}]$lib$::jsonb
);

-- library-source: lally_2010_habit_formation sha256:feaf623320141125a8316d62ead137cf1e2c1b8e074cfc41d6034cfe5f2ec2f4
select private.library_replace_source(
$lib${"slug":"lally_2010_habit_formation","title":"How are habits formed: modelling habit formation in the real world","authors":["Lally P","van Jaarsveld CHM","Potts HWW","Wardle J"],"year":2010,"doi":"10.1002/ejsp.674","url":"https://doi.org/10.1002/ejsp.674","licence":"Publisher copyright (no open licence found); stored as an own-words summary with citation","region":["global"],"topics":["behaviour-change","habits","adherence","consistency","coaching-communication"],"evidence_level":"observational study (96 volunteers over 12 weeks)","kind":"paper"}$lib$::jsonb,
$lib$[{"ordinal":0,"section":"What the study did","header":"Source: Lally et al. 2010, How are habits formed: modelling habit formation in the real world. Section: What the study did.","body":"Ninety-six volunteers each picked one eating, drinking or activity behaviour and did it every day in the same situation, for example after breakfast, for 12 weeks. Every day they rated how automatic the behaviour felt and recorded whether they did it. Eighty-two gave enough data to analyse.","token_count":104},{"ordinal":1,"section":"Results","header":"Source: Lally et al. 2010, How are habits formed: modelling habit formation in the real world. Section: Results.","body":"Automaticity rose in a curve that climbs quickly at first and then levels off. The model fitted for 62 people, and fitted well for 39 of them. Doing the behaviour more consistently went with a better fit. The time to reach 95 percent of each person's own plateau ranged from 18 to 254 days, so it can take a very long time and differs a great deal between people. Missing a single opportunity did not materially affect the process.","token_count":136},{"ordinal":2,"section":"Practical reading and limits","header":"Source: Lally et al. 2010, How are habits formed: modelling habit formation in the real world. Section: Practical reading and limits.","body":"Coach should not promise a fixed number of days to form a habit. The findings support small, specific actions tied to a steady cue, repeated consistently, and treating a missed day as no reason to quit. The volunteers chose their own behaviour and rated automaticity themselves, and the study did not test complex routines such as a full training programme.","token_count":123}]$lib$::jsonb
);

-- library-source: mujika_2001_muscular_detraining sha256:45f13101cffcd4ca8f169df37584f723a96ed1967205a482fc0174afe254359b
select private.library_replace_source(
$lib${"slug":"mujika_2001_muscular_detraining","title":"Muscular characteristics of detraining in humans","authors":["Mujika I","Padilla S"],"year":2001,"doi":"10.1097/00005768-200108000-00009","url":"https://doi.org/10.1097/00005768-200108000-00009","licence":"Publisher copyright (no open licence found); stored as an own-words summary with citation","region":["global"],"topics":["detraining","training","strength","recovery","time-off"],"evidence_level":"narrative review","kind":"paper"}$lib$::jsonb,
$lib$[{"ordinal":0,"section":"What detraining is","header":"Source: Mujika and Padilla 2001, Muscular characteristics of detraining in humans. Section: What detraining is.","body":"During periods when the training stimulus is too low, muscle detrains: it loses part of what training built. The review describes what happens inside muscle in people who stop training.","token_count":75},{"ordinal":1,"section":"Strength and muscle size","header":"Source: Mujika and Padilla 2001, Muscular characteristics of detraining in humans. Section: Strength and muscle size.","body":"Strength performance is in general readily maintained for up to four weeks of inactivity. The exceptions are the eccentric force and sport-specific power of highly trained athletes, and strength that was gained recently, which may fall significantly. Muscle fibre size drops quickly in strength and sprint athletes, while force production declines slowly, in line with a fall in the muscle's electrical activity (EMG). The mix of fibre types stays unchanged during the first weeks.","token_count":150},{"ordinal":2,"section":"Endurance-related changes","header":"Source: Mujika and Padilla 2001, Muscular characteristics of detraining in humans. Section: Endurance-related changes.","body":"The finer blood-supply and energy-production features of muscle start to change sooner: capillary density can fall within two to three weeks of inactivity, and oxygen extraction from the blood declines if the stoppage goes beyond three to eight weeks. These features remain above untrained levels in a detrained athlete but usually return to baseline in someone who trained only recently.","token_count":127},{"ordinal":3,"section":"Practical reading and limits","header":"Source: Mujika and Padilla 2001, Muscular characteristics of detraining in humans. Section: Practical reading and limits.","body":"A break of one to three weeks is unlikely to erase strength in someone who has trained for a while, although muscle fibre size can shrink early and recently gained strength is the least secure. Longer breaks cost more. The review is about stopping altogether, so light activity during the break is not covered, and as a narrative review it is not a pooled analysis, so the effect for a particular lifter is an estimate.","token_count":136}]$lib$::jsonb
);

-- library-source: bosquet_2013_training_cessation sha256:9ab77f05b4d8244ff0f37c9daf4d3fc25f77a97a4f4991c2ce2895d777d6eb7a
select private.library_replace_source(
$lib${"slug":"bosquet_2013_training_cessation","title":"Effect of training cessation on muscular performance: a meta-analysis","authors":["Bosquet L","Berryman N","Dupuy O","Mekary S","Arvisais D","Bherer L"],"year":2013,"doi":"10.1111/sms.12047","url":"https://doi.org/10.1111/sms.12047","licence":"Publisher copyright (no open licence found); stored as an own-words summary with citation","region":["global"],"topics":["detraining","training","strength","time-off","older-adults"],"evidence_level":"meta-analysis (103 studies)","kind":"paper"}$lib$::jsonb,
$lib$[{"ordinal":0,"section":"What the analysis did","header":"Source: Bosquet et al. 2013, Effect of training cessation on muscular performance: a meta-analysis. Section: What the analysis did.","body":"The authors searched seven databases and pooled 103 studies of resistance training cessation, grouping the results by training status, sex, age and the length of the break.","token_count":76},{"ordinal":1,"section":"Results","header":"Source: Bosquet et al. 2013, Effect of training cessation on muscular performance: a meta-analysis. Section: Results.","body":"Stopping resistance training reduced every component of muscular performance: submaximal strength (a standardised effect of -0.62), maximal force (-0.46) and maximal power (-0.20), so the pooled effect was larger for submaximal strength than for power. The loss grew with the length of the break. It was larger in people over 65, and for maximal force and power it was larger in inactive people than in recreational athletes.","token_count":136},{"ordinal":2,"section":"Practical reading and limits","header":"Source: Bosquet et al. 2013, Effect of training cessation on muscular performance: a meta-analysis. Section: Practical reading and limits.","body":"Stopping does cost strength, more so the longer it lasts, and for maximal force and power the cost was smaller in recreational athletes than in inactive people. The abstract does not give weeks or percentages, so this source cannot be used to quote how much is lost after a particular number of weeks. Taken with Mujika and Padilla, it supports saying that a couple of weeks off is unlikely to be a setback for a regular lifter.","token_count":142}]$lib$::jsonb
);

-- library-source: lopes_2019_elastic_resistance sha256:275b320f045add2a08a4b13462e4066bedb8491beee43e42e59f86c1ef468bfb
select private.library_replace_source(
$lib${"slug":"lopes_2019_elastic_resistance","title":"Effects of training with elastic resistance versus conventional resistance on muscular strength: a systematic review and meta-analysis","authors":["Lopes JSS","Machado AF","Micheletti JK","de Almeida AC","Cavina AP","Pastre CM"],"year":2019,"doi":"10.1177/2050312119831116","url":"https://doi.org/10.1177/2050312119831116","licence":"CC BY-NC (open access); own-words summary, no text copied","region":["global"],"topics":["home-training","equipment","strength","training","minimal-equipment"],"evidence_level":"systematic review and meta-analysis (8 studies)","kind":"paper"}$lib$::jsonb,
$lib$[{"ordinal":0,"section":"What the review did","header":"Source: Lopes et al. 2019, Effects of training with elastic resistance versus conventional resistance on muscular strength: a systematic review and meta-analysis. Section: What the review did.","body":"Elastic resistance (tubes and bands) is cheap and easy to use, so the reviewers compared training with it against training with conventional equipment (weight machines and dumbbells) on muscular strength. They searched four databases up to December 2017 and pooled eight studies.","token_count":118},{"ordinal":1,"section":"Results","header":"Source: Lopes et al. 2019, Effects of training with elastic resistance versus conventional resistance on muscular strength: a systematic review and meta-analysis. Section: Results.","body":"Neither method was better for lower-limb strength or upper-limb strength. The authors conclude that elastic resistance training can produce strength gains similar to conventional training, across different groups of people and different training protocols.","token_count":110},{"ordinal":2,"section":"Practical reading and limits","header":"Source: Lopes et al. 2019, Effects of training with elastic resistance versus conventional resistance on muscular strength: a systematic review and meta-analysis. Section: Practical reading and limits.","body":"A person without a gym can reasonably expect to keep and even build strength with bands, and Coach should not call that second-best. Only eight studies were pooled, and the abstract does not say how muscle size changed. Another source in the library (Lopez 2021) covers lighter loads taken close to failure. This review does not test bodyweight training, so Coach should not claim bodyweight exercise works as well as weights on the strength of this paper alone.","token_count":166}]$lib$::jsonb
);

-- library-source: fragala_2019_older_adults sha256:097daa61139731e33d82d3b35b4159549f72010f047c076dca648873f62f76f4
select private.library_replace_source(
$lib${"slug":"fragala_2019_older_adults","title":"Resistance training for older adults: position statement from the National Strength and Conditioning Association","authors":["Fragala MS","Cadore EL","Dorgo S","Izquierdo M","Kraemer WJ","Peterson MD"],"year":2019,"doi":"10.1519/jsc.0000000000003230","url":"https://doi.org/10.1519/jsc.0000000000003230","licence":"Publisher copyright (no open licence found); stored as an own-words summary with citation","region":["global"],"topics":["older-adults","strength","training","safety","guidelines"],"evidence_level":"position statement","kind":"position_stand"}$lib$::jsonb,
$lib$[{"ordinal":0,"section":"Why it matters","header":"Source: Fragala et al. 2019 (NSCA), Resistance training for older adults: position statement from the National Strength and Conditioning Association. Section: Why it matters.","body":"Ageing, even without chronic disease, brings biological changes that can reduce skeletal muscle mass, strength and function, which lowers resilience and raises vulnerability to serious events. The position statement argues that countering muscle disuse through resistance training is a powerful way to fight the loss of strength and muscle and their consequences for physical function, mobility, independence, chronic disease management, wellbeing, quality of life and healthy life expectancy.","token_count":167},{"ordinal":1,"section":"What it covers","header":"Source: Fragala et al. 2019 (NSCA), Resistance training for older adults: position statement from the National Strength and Conditioning Association. Section: What it covers.","body":"The statement gives evidence-based recommendations in four parts: programme design variables, physiological adaptations, functional benefits, and considerations for frailty, sarcopenia and other chronic conditions. Its stated aims are a more unified approach, promotion of the health and functional benefits, and reducing fears and barriers to starting.","token_count":132},{"ordinal":2,"section":"Practical reading and limits","header":"Source: Fragala et al. 2019 (NSCA), Resistance training for older adults: position statement from the National Strength and Conditioning Association. Section: Practical reading and limits.","body":"This summary is written from the abstract, which gives no sets, loads or frequencies, so Tracend's rules and the shared training sources set those. The usable message for Coach is that older adults benefit from lifting and that fear and other barriers to starting are worth addressing kindly. Frailty, sarcopenia and chronic conditions are matters for a professional, and Coach does not plan rehabilitation. This is a peer-reviewed journal article; the association's courses and textbooks are not used.","token_count":173}]$lib$::jsonb
);

-- library-source: mcnulty_2020_menstrual_cycle sha256:0c010ab8a1b565d9c610c6060e740fb1565e26381962f770cd292ddf22f60e66
select private.library_replace_source(
$lib${"slug":"mcnulty_2020_menstrual_cycle","title":"The effects of menstrual cycle phase on exercise performance in eumenorrheic women: a systematic review and meta-analysis","authors":["McNulty KL","Elliott-Sale KJ","Dolan E","Swinton PA","Ansdell P","Goodall S"],"year":2020,"doi":"10.1007/s40279-020-01319-3","url":"https://doi.org/10.1007/s40279-020-01319-3","licence":"CC BY 4.0 (open access); own-words summary","region":["global"],"topics":["women","menstrual-cycle","performance","training","individualisation"],"evidence_level":"systematic review and network meta-analysis (78 studies)","kind":"paper"}$lib$::jsonb,
$lib$[{"ordinal":0,"section":"What the review did","header":"Source: McNulty et al. 2020, The effects of menstrual cycle phase on exercise performance in eumenorrheic women: a systematic review and meta-analysis. Section: What the review did.","body":"Sex hormones change across the menstrual cycle, and results on whether this affects exercise performance conflict. The authors followed standard systematic review rules, searched four databases and included 78 studies of women with regular cycles, 51 of which could be pooled in a first analysis comparing the early follicular phase (the early part of the cycle) with all other phases. A broader network analysis compared every phase with every other using 73 studies.","token_count":163},{"ordinal":1,"section":"Results","header":"Source: McNulty et al. 2020, The effects of menstrual cycle phase on exercise performance in eumenorrheic women: a systematic review and meta-analysis. Section: Results.","body":"Performance might be trivially lower in the early follicular phase than in the other phases, for both endurance and strength outcomes. The largest difference was between the early follicular and the late follicular phase, and it was small. The quality of the evidence was low.","token_count":112},{"ordinal":2,"section":"Practical reading and limits","header":"Source: McNulty et al. 2020, The effects of menstrual cycle phase on exercise performance in eumenorrheic women: a systematic review and meta-analysis. Section: Practical reading and limits.","body":"Because the effect is trivial, the variation between studies is large and many included studies were of poor quality, the authors say general guidelines on exercise across the cycle cannot be made and recommend a personalised approach based on how each woman responds. Coach should therefore not change a plan by cycle day by default, but should listen when a woman reports a pattern in her own training. The review covers women with regular cycles, not irregular cycles, hormonal contraception or the menopause, and Coach should not give medical advice on these.","token_count":189}]$lib$::jsonb
);

